import{_ as t,H as a,f as p,i}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"02 | 业务体验性的三大挑战与思路探讨","description":"","frontmatter":{},"headers":[{"level":2,"title":"业务体验性有哪些困境？","slug":"业务体验性有哪些困境","link":"#业务体验性有哪些困境","children":[{"level":3,"title":"一、交互式体验落后","slug":"一、交互式体验落后","link":"#一、交互式体验落后","children":[]},{"level":3,"title":"二、数字化深度不够","slug":"二、数字化深度不够","link":"#二、数字化深度不够","children":[]},{"level":3,"title":"三、智能化程度不足","slug":"三、智能化程度不足","link":"#三、智能化程度不足","children":[]}]},{"level":2,"title":"业务体验性困境的解决思路","slug":"业务体验性困境的解决思路","link":"#业务体验性困境的解决思路","children":[{"level":3,"title":"一、交互体验落后的解决思路","slug":"一、交互体验落后的解决思路","link":"#一、交互体验落后的解决思路","children":[]},{"level":3,"title":"二、数字化深度不够的解决思路","slug":"二、数字化深度不够的解决思路","link":"#二、数字化深度不够的解决思路","children":[]},{"level":3,"title":"三、智能化程度不足的解决思路","slug":"三、智能化程度不足的解决思路","link":"#三、智能化程度不足的解决思路","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"智能原生架构实战/02｜业务体验性的三大挑战与思路探讨.md","filePath":"智能原生架构实战/02｜业务体验性的三大挑战与思路探讨.md","lastUpdated":1795558194000}'),n={name:"智能原生架构实战/02｜业务体验性的三大挑战与思路探讨.md"};function l(s,e,r,E,o,h){return a(),p("div",null,[...e[0]||(e[0]=[i('<h1 id="_02-业务体验性的三大挑战与思路探讨" tabindex="-1">02 | 业务体验性的三大挑战与思路探讨 <a class="header-anchor" href="#_02-业务体验性的三大挑战与思路探讨" aria-label="Permalink to &quot;02 | 业务体验性的三大挑战与思路探讨&quot;">​</a></h1><p>你好，我是灵犀。</p><p>说到业务体验性，许多人会认为，指的不就是用户在使用产品时爽不爽吗？但在今天的课程中，我们要对这一概念进行全新升级！</p><p>传统定义的业务体验性，一般用来指人机交互过程中用户所产生的感受、认知与情感反馈的总和。可以看到，主角是人，因为流程基本由人来驱动。</p><p>但是，到了数字化时代，数据也可以驱动流程。而到了智能化时代，模型（知识）更是可以进一步替代人来完成一些决策。因此，业务体验性就不能只考虑人的感受了，那又该如何考虑数据、模型（知识）的“感受”呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/1.png" alt=""></a></p><p>带着这个问题，接下来，我们就开始讨论业务体验性方面面临的困境、剖析原因并简要探讨解决思路。</p><h2 id="业务体验性有哪些困境" tabindex="-1">业务体验性有哪些困境？ <a class="header-anchor" href="#业务体验性有哪些困境" aria-label="Permalink to &quot;业务体验性有哪些困境？&quot;">​</a></h2><p>我们还是先看看传统模式下，有哪些原因导致了系统的业务体验不够“爽”？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/2.jpeg" alt=""></a></p><h3 id="一、交互式体验落后" tabindex="-1">一、交互式体验落后 <a class="header-anchor" href="#一、交互式体验落后" aria-label="Permalink to &quot;一、交互式体验落后&quot;">​</a></h3><p>当前大多数企业系统仍沿用传统的交互方式，如菜单导航、表单填写、按钮点击等，整体体验相对陈旧，在实际使用中存在以下突出问题。</p><p>1.层级跳转繁多，操作效率低</p><p>用户通常需要经历多个菜单层级才能访问目标功能，路径冗长、步骤复杂，尤其在移动端或高频操作场景下，严重影响使用效率和体验。</p><ol start="2"><li>交互方式单一，缺乏多样性</li></ol><p>当前系统主要依赖鼠标点击或触摸操作，交互形式较为单一，缺少自然语言交互、多模态交互等新型交互方式。这不仅限制了不同用户群体的使用习惯适配，也难以满足多样化业务场景下的灵活操作需求，尤其在处理复杂业务流程时显得效率低下、体验僵化。</p><ol start="3"><li>缺乏智能感知，多被动响应</li></ol><p>多数系统仍停留在“用户发起—系统响应”的被动交互模式，缺乏对用户行为的智能感知与主动服务能力。例如，系统无法根据用户使用习惯推荐常用功能，无法基于行为数据预警潜在风险，也无法在合适时机主动推送相关服务信息，导致整体服务体验缺乏温度和智能性。</p><h3 id="二、数字化深度不够" tabindex="-1">二、数字化深度不够 <a class="header-anchor" href="#二、数字化深度不够" aria-label="Permalink to &quot;二、数字化深度不够&quot;">​</a></h3><p>在数字化建设过程中，传统交互层面的体验优化虽然能够提升用户的直观感受，但这更多属于“冰山之上”的部分。真正决定企业业务效率与运营能力的，是隐藏在表象之下的“数字化深度”。而目前，企业在这一维度上仍存在诸多短板。我们具体来看看最突出的三点。</p><p>1.流程中存在断点</p><p>目前许多企业在流程线上化方面已取得一定进展，但仍普遍存在“断点”现象：一个本应端到端闭环的业务流程，部分环节已实现系统化处理，但仍有部分依赖线下的人工操作，或通过邮件、短信等方式进行通知与传递。</p><p>这种“线上 + 线下”混合运行的模式，不仅降低了整体流程效率，也增加了操作风险和管理成本。</p><p>断点问题往往出现在跨业务条线的系统边界之间。这背后的原因，正是传统“烟囱式”建设模式所导致的：系统边界由业务边界直接决定，缺乏统一规划与协同设计。</p><p>2.人与系统协同差</p><p>部分企业数字化水平更进一步，基本实现了流程的线上化，但在人与系统的协同效率上仍有较大提升空间。</p><p>例如，有些企业通过构建统一门户系统，将一些关联较深领域的功能菜单集中展示，并提供个人工作台，使得用户可以在一个系统界面中完成大部分操作。</p><p>表面上看实现了“功能聚合”，但深入去看，用户仍需按照业务流程在不同菜单之间反复跳转，缺乏流程的自然引导与自动推进。业务流程依然停留在“人找功能”的阶段，系统仍是被动响应的工具，尚未实现主动协同。</p><p>换句话说，目前的模式仍是“人驱动系统干活”，离“系统驱动人完成工作”尚有不少距离。</p><p>3.系统之间协同差</p><p>流程交互体验的问题不仅体现在人与系统的深度交互层面，也广泛存在于系统之间的协同层面。</p><p>在企业复杂的业务体系中，系统往往存在上下游的依赖关系。当上游系统发生接口或数据结构的变更时，目前主要依赖人工方式进行通知和对接，下游系统容易出现遗漏、延迟或对接错误，从而引发一系列问题。</p><p>这种系统间缺乏自动化感知和协同机制的问题，也是在数字化进程中亟需解决的问题。</p><h3 id="三、智能化程度不足" tabindex="-1">三、智能化程度不足 <a class="header-anchor" href="#三、智能化程度不足" aria-label="Permalink to &quot;三、智能化程度不足&quot;">​</a></h3><p>当前企业在智能化建设方面，整体仍处于初级阶段。我们可以从能力层级上，将“智能化”划分为三个递进层次：单点智能、流程智能和商业智能。下面逐一进行说明。</p><p>1.单点智能居多</p><p>目前，大多数企业的智能化应用仍集中于单点智能阶段。例如，OCR 识别、PDF 内容提取、图像分类、自然语言处理等 AI 能力，已广泛嵌入各类业务场景中，成为提升效率、优化体验的技术工具。</p><p>然而，这些智能能力在实际应用中往往扮演的是“被动响应”的角色——即只有在用户明确调用、指定参数或触发条件时才会执行，缺乏对业务流程上下文的理解与主动参与能力。换句话说，智能更多是作为“功能模块”嵌入现有流程，尚未实现与业务逻辑的深度融合。</p><p>2.流程智能欠缺</p><p>与单点智能相比，流程智能的发展尚不成熟。所谓流程智能，是指将 AI 能力深度嵌入业务流程中，使其能够自动识别流程节点、判断执行条件、推荐操作路径，甚至在特定场景下具备一定的自主决策和执行能力。</p><p>例如，在审批流程中，系统是否可以根据历史数据自动识别风险等级并推荐审批路径？在客户服务流程中，系统是否能结合用户画像与问题上下文，主动推送解决方案？这类流程驱动的智能优化，目前在企业中的应用仍较为有限，仍有巨大的发展空间。</p><p>值得注意的是，当前“智能体”（Agent）的发展也是为了解决流程自动化问题。</p><p>然而，受限于当前大模型对企业内部专业知识语义理解能力的不足，智能体在推理与决策层面的表现，尚难以完全满足复杂业务场景的需求。</p><p>3.商业智能罕见</p><p>更高层级的智能化——商业智能，目前在企业中仍较为罕见。商业智能通常涉及企业战略层面的重构，如商业模式创新、运营机制优化、客户价值深度挖掘等。它不仅需要强大的数据基础和算法支撑，更需要深度结合行业特性与企业自身的业务发展阶段。</p><p>因此，这部分内容在这门课里暂不展开，但这里提及，是因为这点值得在未来的智能化进阶实践中重点关注。</p><h2 id="业务体验性困境的解决思路" tabindex="-1">业务体验性困境的解决思路 <a class="header-anchor" href="#业务体验性困境的解决思路" aria-label="Permalink to &quot;业务体验性困境的解决思路&quot;">​</a></h2><p>下面，我们就针对前面三个困境探讨一下解决思路。</p><h3 id="一、交互体验落后的解决思路" tabindex="-1">一、交互体验落后的解决思路 <a class="header-anchor" href="#一、交互体验落后的解决思路" aria-label="Permalink to &quot;一、交互体验落后的解决思路&quot;">​</a></h3><p>我们可以从 Gartner 提出的客户体验金字塔模型出发，作为理解客户体验的重要参考，该模型将客户体验分为五个层次：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/3.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/3.jpeg" alt=""></a></p><p>如果我们从“信息流”的角度来看人机交互，会发现客户体验本质上就是人与系统之间信息流传递与处理的过程。</p><p>基于这一视角，再来审视 Gartner 的模型，我们又会有怎样的发现呢？</p><p>在第一到第三层中，信息流主要由用户主动发起，系统的目标是高效、准确地响应用户请求，实现简洁、清晰的交互体验。</p><p>到达第四层及以上时，信息流模式开始发生变化，系统不仅要响应用户的主动输入，还需具备主动推送信息的能力。这就要求系统具备对用户意图的预测能力，能够在合适的时机、以合适的方式提供相关服务。</p><p>当前，随着人工智能与用户体验设计的不断发展，越来越多的新型交互方式正在兴起，为优化传统交互方式提供了新的可能。比如，大模型的问答式和多模态交互、华为鸿蒙的微卡片设计等。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/4.png" alt=""></a></p><ul><li>多模态交互案例</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/5.png" alt=""></a></p><ul><li>华为鸿蒙的微卡片设计 图源：<a href="https://developer.huawei.com/consumer/cn/training/course/live/C101730105347358932" target="_blank" rel="noreferrer">https://developer.huawei.com/consumer/cn/training/course/live/C101730105347358932</a></li></ul><p>未来，在构建“轻交互”体系时，我们应围绕两个核心理念展开设计。一是“用户所得即所想”，确保系统反馈与用户需求高度一致，最大程度减少无效交互；二是“想用户之所想”，实现“服务找人”的智能化交互体验。</p><p>但是，就像上节课所说，这个过程中如何尽可能降低大模型的幻觉是一个很大的挑战。</p><p>关于这一理念的具体落地路径与实现方式，我们后续关于“立体感知”能力建设的课程里，还会进一步介绍整体解决方案。</p><h3 id="二、数字化深度不够的解决思路" tabindex="-1">二、数字化深度不够的解决思路 <a class="header-anchor" href="#二、数字化深度不够的解决思路" aria-label="Permalink to &quot;二、数字化深度不够的解决思路&quot;">​</a></h3><p>前面我们分析了当前企业在数字化深化过程中，主要存在的三类问题：流程中存在断点、人与系统协同差、系统之间协同差。</p><p>要解决这些问题，首先需要回归本质，厘清“数字化”的真正内涵。</p><p>从字面意义来看，数字化是指将物理世界中的业务流程通过数字的方式进行表达，从而将传统信息转化为可被计算机分析和处理的数据。由于数字世界是一个规则明确、逻辑严谨的世界，计算机在处理这类任务时具有天然优势，能够显著提升效率。</p><p>由于数字化是在信息化基础上的进一步发展，上述定义好像仍难以让人直观区分二者的差异。实际上，二者的核心区别，在于对数据的认知层面存在不同。</p><p>在信息化时代，我们将线下流程迁移至线上系统中，由人主动操作并驱动系统运行。系统在此过程中扮演的是一个“被动”角色，主要功能是支撑人工流程的完成，整体上属于“人驱动系统干活”的模式。</p><p>而进入数字化时代，最大的变量来自于“数据”。此时，企业已通过信息化阶段积累了大量数据资源。这些数据的价值不仅在于存储和展示，更在于其能够被挖掘、分析，并反作用于业务流程。</p><p>我们可以通过两个时代的典型产品来理解这种变化。一个是百度，信息化时代的典型代表，其核心模式是“人找信息”。另一个是今日头条，数字化时代的典型代表，其核心模式是“信息找人”。</p><p>这一转变的背后，正是数据驱动的力量。通过分析，数据具备了一些“拟人化”的特征，它甚至可以比你的好朋友更了解你的偏好和需求，从而能够实现“主动服务”。</p><p>在企业应用场景中也是如此。相比于信息化阶段，数字化阶段的最大变化在于：从“人驱动系统干活”转变为“系统驱动人干活”。而实现这一转变的底层逻辑，正是数据驱动。</p><p>因此，前面所提到的三个问题的解决思路是统一的：充分发挥数据的价值，让数据“跑起来”，通过数据去打通断点，以及提升人与系统、系统与系统间的协同效率。</p><p>在后面设计篇和实现篇里，我会再具体讨论相关的设计和落地技术方案，这里你先有个印象，记住“数据驱动”这个关键点。</p><h3 id="三、智能化程度不足的解决思路" tabindex="-1">三、智能化程度不足的解决思路 <a class="header-anchor" href="#三、智能化程度不足的解决思路" aria-label="Permalink to &quot;三、智能化程度不足的解决思路&quot;">​</a></h3><p>首先，我们还是要回答什么是智能化？它与数字化的本质区别又是什么？</p><p>前面我们已经知道了，数字化是信息化的进一步延伸，而智能化则是建立在数字化基础之上的更高阶段。</p><p>如果用一句话来概括智能化的本质，那就是拟人化。人最大的特点是什么？其实就是思考。那智能化，其实就是让系统能够做更多的“思考”。</p><p>我们可以将整个企业看作一个大的系统。这个系统能够日常运转起来，靠的是“思考”的能力。就像人一样，人的能力也取决于此。</p><p>在信息化时代，企业的“思考”主要是人来完成的。此时的 BI 商业洞察或统计分析，都是事后辅助于人的，并没有主动思考并采取行动。</p><p>到了数字化时代，企业的“思考”变成了“人 + 数据”。系统通过数据驱动的方式，可以自主完成一些任务，但这种“思考”依然是在数据分析基础之上基于明确的规则和确定性的逻辑。</p><p>而智能化时代的出现，尤其是大模型的引入，让系统具备了“类人”的认知能力。如果说大模型更多承担的是“理解”角色，能够“说”却难以“做”，缺乏实际执行能力，那么智能体（Agent）则更进一步，标志着 AI 迈入从“理解”到“行动”的新阶段。</p><p>智能体就相当于是一个“数字劳动力”，能够理解、推理、判断，在一定程度上应对不确定性与复杂场景。</p><p>因此，智能化与数字化的本质区别在于：数字化仍然基于规则和数据规律，倾向于解决确定性问题；而智能化则更进一步，能处理不确定性、复杂性更强的任务。</p><p>回到我们之前提到的智能化不足问题，如单点智能、流程智能、商业智能的缺失，其实质是在企业的业务链条中，缺乏足够的“系统思考”能力。也就是说，数据在流转过程中，还缺乏将数据转化为信息、信息再转化成知识，由知识形成决策的机制。</p><p>由此我们就能找到关键了，要解决这些问题，核心就是在更多业务节点中注入智能化能力，让系统具备主动感知、推理和判断的能力，从而实现数据流的自动转化和决策。</p><p>在后续“实现篇”的“智能决策”那节课，我还会为你分享更为具体的技术实现路径和落地方法，敬请期待。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我们首先扩展了业务体验性的内涵，将其由传统的人机交互升级为人、机、数据和模型之间的多维交互。</p><p>接着，我们深入分析了业务体验性面临的三大挑战，分别是交互式体验落后、数字化深度不足以及智能化程度不足。这些挑战背后的本质原因，其实都可以归结为：在一个由人、机、数据和模型所构成的高维网络空间中，信息在流动过程中出现的诸如冗余、被动响应、断点、卡顿、摩擦等现象。</p><p>基于这一认知，我们进一步探讨了关键的解决思路，核心可以概括为：如何让信息在这个复杂的高维网络空间中，更快、更好地到达指定的地方。</p><p>再回到这节课最初的问题：我们该如何考虑数据、模型（知识）的“感受”呢？答案就是：让数据、模型（知识）变得越来越像“人”一样，多主动去干活，而“人”则变得越来越像传统意义上的“机器”一样，少干活甚至不干活。</p><p>那如何去实现呢？这也正是智能原生架构要重点解决的问题，我们在后续方法篇和实战篇中还会继续讨论。</p><p>另外这节课的重点我为你梳理了一张知识导图，方便你总结复习。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%99%BA%E8%83%BD%E5%8E%9F%E7%94%9F%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98/images/02/6.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>在企业数字化转型过程中，不论业务还是技术都希望能解决更多、更深刻的问题。然而，解决问题的关键首先是定义问题。按照这节课中对业务体验性的定义，你认为影响业务体验性的关键问题还有哪些？</p><p>期待你在留言区和我交流互动，如果这节课对你有启发，别忘了分享给身边更多朋友。</p>',99)])])}const g=t(n,[["render",l]]);export{u as __pageData,g as default};
